<?php
if(!defined('ABSPATH'))exit;
function dgs_school_checklist($items,$name,$legend,$placeholder,$unit,$alert){$h='<fieldset class="dgs-bulk-picker" data-bulk-unit="'.esc_attr($unit).'" data-bulk-alert="'.esc_attr($alert).'"><legend>'.esc_html($legend).'</legend><input type="search" data-bulk-search placeholder="'.esc_attr($placeholder).'" aria-label="'.esc_attr($placeholder).'"><label class="dsp-checkbox"><input type="checkbox" data-bulk-all>انتخاب همه موارد نمایش‌داده‌شده</label><div class="dgs-bulk-items">';foreach($items as $id=>$label)$h.='<label class="dsp-checkbox" data-bulk-item><input type="checkbox" name="'.esc_attr($name).'[]" value="'.(int)$id.'"><span>'.esc_html($label).'</span></label>';return $h.'</div><small data-bulk-count>۰ '.esc_html($unit).' انتخاب شده</small></fieldset>';}
function dgs_school_student_checklist($students){return dgs_school_checklist($students,'student_ids','انتخاب دانش‌آموزان','جست‌وجوی نام دانش‌آموز','نفر','حداقل یک دانش‌آموز انتخاب کنید.');}
function dgs_school_class_checklist($classes){return dgs_school_checklist($classes,'class_ids','کلاس‌ها','جست‌وجوی کلاس','کلاس','حداقل یک کلاس انتخاب کنید.');}
function dgs_school_assign_student($d){
 if(!isset($d['student_ids']))return dgs_school_assign_one($d);
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','اجازه مدیریت ندارید.');$raw=$d['student_ids'];unset($d['student_ids']);foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','درخواست معتبر نیست.');if(!is_array($raw)||!$raw||count($raw)>2000)return dgs_edu_error('students','حداقل یک دانش‌آموز انتخاب کنید (حداکثر۲۰۰۰ نفر).');$ids=[];foreach($raw as $v){if(!is_scalar($v)||!ctype_digit((string)$v)||(int)$v<1)return dgs_edu_error('students','انتخاب دانش‌آموز معتبر نیست.');$ids[]=(int)$v;}$ids=array_unique($ids);$year=dgs_edu_year((string)($d['year']??''));$class=dgs_edu_class($d['class_id']??0);if(!$class||!$year||$class->school_year!==$year)return dgs_edu_error('class','کلاس مقصد همین سال را انتخاب کنید.');global $wpdb;$tables=dgs_edu_tables();foreach($ids as $id){if(!dgs_edu_role($id,'dgs_student'))return dgs_edu_error('students','یکی از حساب‌های انتخاب‌شده دانش‌آموز نیست.');$old=$wpdb->get_var($wpdb->prepare("SELECT class_id FROM {$tables['enrollments']} WHERE student_id=%d AND school_year=%s",$id,$year));if($old&&(int)$old!==(int)$class->id&&($d['replace']??'')!=='1')return dgs_edu_error('replace','برای انتقال دانش‌آموزان دارای کلاس، تیک تأیید انتقال را بزنید؛ هنوز تغییری ثبت نشده است.');}
 if($wpdb->query('START TRANSACTION')===false)return dgs_edu_error('write','ثبت گروهی شروع نشد.');foreach($ids as $id){$r=dgs_school_assign_one(array_merge($d,array('student_id'=>$id)),true);if(is_wp_error($r)){$wpdb->query('ROLLBACK');return $r;}}if($wpdb->query('COMMIT')===false){$wpdb->query('ROLLBACK');return dgs_edu_error('write','ثبت گروهی کامل نشد.');}return dgs_fa_digits(count($ids)).' دانش‌آموز به کلاس مقصد منتسب شدند؛ سوابق قبلی حفظ شد.';
}
add_action('wp_enqueue_scripts',function(){if(!dgs_is_role_portal()||!current_user_can('dgs_manage_education'))return;wp_register_script('dgs-bulk-assign',false,array(),DGS_VERSION,true);wp_enqueue_script('dgs-bulk-assign');wp_add_inline_script('dgs-bulk-assign',file_get_contents(DGS_PATH.'assets/student-bulk-assign.js'));wp_register_style('dgs-bulk-assign',false,array(),DGS_VERSION);wp_enqueue_style('dgs-bulk-assign');wp_add_inline_style('dgs-bulk-assign','.dgs-bulk-items{max-height:260px;overflow:auto;border:1px solid #dfcbef;border-radius:10px;padding:8px}.dgs-bulk-items>label{display:flex;gap:8px;padding:6px;margin:0}.dgs-bulk-items>label[hidden]{display:none}.dgs-bulk-picker{border:0;padding:0;margin:0 0 12px}.dgs-bulk-picker input[type=checkbox]{width:18px;min-height:18px;flex-shrink:0}.dgs-bulk-picker small{display:block;margin-top:6px}');});
